    # return the position of target, or -1
    return -1

steps.solution:
def find(names, target):
    for i in range(len(names)):
        if names[i] == target:
            return i
    return -1

steps.starter:
def is_sorted(a):
    # True if every item is <= the next one
    return False

steps.solution:
def is_sorted(a):
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            return False
    return True

steps.starter:
def count_above(values, limit):
    # return how many values are greater than limit
    return 0

steps.solution:
def count_above(values, limit):
    count = 0
    for v in values:
        if v > limit:
            count = count + 1
    return count

